\name{updateStore}
\alias{updateStore}
\title{Update local storage}
\usage{
updateStore(session, name, value, encrypt = NULL)
}
\arguments{
  \item{session}{The session paramter from the
  \code{\link{shinyServer}} function.}

  \item{name}{The name for this setting. This is the name
  you'll reference later when you want to retrieve this
  value from your storage object.}

  \item{value}{The value for this setting. Can be a string,
  in which case it will be passed through unbothered, or a
  more complex object which will be translated to JSON.}

  \item{encrypt}{If NULL (the default), the field will not
  be encrypted. Otherwise, it will expect a PKI public key
  in the form generated by \code{\link{PKI.load.key}} which
  will then be used to encrypt the fields.}
}
\description{
Send the name of the field to update and the value which
should be stored in this user's local storage.
}

shinyStore = (function(){ 
  var exports = {};

  var namespace;

  function supports_html5_storage() {
    try {
      return 'localStorage' in window && window['localStorage'] !== null;
    } catch (e) {
      return false;
    }
  }

  if (!supports_html5_storage){
    alert("ls not supported")
    return;
  }


  // Add callbacks which will be called with (key, val) when an update occurs.
  var callbacks = [];
  exports.addCallback = function(callback){
    callbacks.push(callback);
  }

  exports.onUpdate = function(key, val){
    $.each(callbacks, function(i, cb){
      cb(key, val)
    })
  }

  // Extract an object representing the local storage that satisfies the current
  // namespace.
  exports.extract = function(){
    var obj = {}
    for ( var i = 0; i < localStorage.length; i++ ) {
      var key = localStorage.key(i);

      if (key.indexOf(namespace + '\\') === 0) {
        obj[key.substring(namespace.length + 1)] = localStorage.getItem(key);
      }
    }
    return obj
  }

  exports.init = function(ns){
    if (namespace != null){
      throw new Error("shinyStore cannot be initialized twice!")
    }
    namespace = ns;
  }

  var shinyStoreInputBinding = new Shiny.InputBinding();
  $.extend(shinyStoreInputBinding, {
    find: function(scope) {
      return $(scope).find(".shiny-store");
    },
    getType: function(){
      return "shinyStore";
    },
    getValue: function(el) {
      return exports.extract()
    },
    setValue: function(el, value) {
      //TODO
    },
    subscribe: function(el, callback) {
      // Register the callback internally
      exports.addCallback(function(k, v){
        callback(exports.extract());
      });
    },
    unsubscribe: function(el) {

    }
  });
  Shiny.inputBindings.register(shinyStoreInputBinding);

  Shiny.addCustomMessageHandler('shinyStore', function(data) {
    $.each(data, function(key, val){
      var newKey = namespace + '\\' + key;
    if (typeof val !== 'string'){
      // If it's not a raw string, JSON.stringify
      val = JSON.stringify(val)
    }
    localStorage[newKey] = val;
    exports.onUpdate(newKey, val);
    });
  });

  handleStorage = function(event){
    if (event.key.indexOf(namespace + '\\') === 0){
      exports.onUpdate(event.key, event.newValue);
    }
  }

  // Thanks to http://cggallant.blogspot.com/2010/07/html-5-web-storage.html
  // Tested on modern Chrome, IE8 and IE9.
  if (window.attachEvent) {
     document.attachEvent('onstorage', handleStorage);
  } else {
      window.addEventListener('storage', handleStorage, false);
  }

  return exports;
})()

(function(){
  // We don't have events we can subscribe to for this, so just update periodically 
  // on a timer.
  var updateEncText = function(){
    var st = localStorage.getItem('shinyStore-ex2\\text');
    // Only update if different
    if ($('#encText').text() !== st){
      $('#encText').text(st); // HTML escapes naturally
    }
  }

  updateEncText() // Run immediately
  setInterval(updateEncText, 500) // Schedule twice/second
})()
